        if (alarmObj && typeof alarmObj.type === 'string') {
          rawType = alarmObj.type;
        }
      } catch (e) {
        // ignora parse error e segue
      }
    }
    // 4) fallback no corpo da mensagem
    if (!rawType && msg && typeof msg.type === 'string') {
      rawType = msg.type;
    }
    if (!rawType && msg && typeof msg.name === 'string') {
      rawType = msg.name;
    }

    // Normalização simples: trim + case-insensitive
    var norm = function (s) {
      return String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
    };

    var lookup = {};
    for (var i = 0; i < allowed.length; i++) {
      lookup[norm(allowed[i])] = true;
    }

    var result = !!lookup[norm(rawType)];

